        int kc1 = 100000;
        int kc2 = 200000;
        int minRoll = 1000;
        int maxRoll = 3000;
        int numObtained = (int) ((minRoll + maxRoll) / 2 * dropChance * (kc1 + kc2));
        double expectedLuck = 0.5;
