        double tolerance = 0.00001;

        InterchangeableSetBinomialDrop drop = (InterchangeableSetBinomialDrop) new InterchangeableSetBinomialDrop(
                new RollInfo(LogItemSourceInfo.ROYAL_TITAN_KILLS, 1.0 / 83.33),
